def solve_2xW_correct(W):
    grid = [[False for _ in range(W)] for _ in range(2)]
    max_S = [0]

    def backtrack(current_S):
        r0, c0 = -1, -1
        for j in range(W):
            for i in range(2):
                if not grid[i][j]:
                    r0, c0 = i, j
                    break
            if r0 != -1: break

        if r0 == -1:
            max_S[0] = max(max_S[0], current_S)
            return

        # Try horizontal domino
        if c0 + 1 < W and not grid[r0][c0+1]:
            grid[r0][c0] = grid[r0][c0+1] = True
            backtrack(current_S)
            grid[r0][c0] = grid[r0][c0+1] = False

        # Try vertical domino
        if r0 == 0 and not grid[1][c0]:
            grid[0][c0] = grid[1][c0] = True
            backtrack(current_S)
            grid[0][c0] = grid[1][c0] = False

        # Try Z-tetrominoes
        # Type 1: {(0,c), (0,c+1), (1,c+1), (1,c+2)}
        if r0 == 0 and c0 + 2 < W:
            if not grid[0][c0+1] and not grid[1][c0+1] and not grid[1][c0+2]:
                grid[0][c0] = grid[0][c0+1] = grid[1][c0+1] = grid[1][c0+2] = True
                backtrack(current_S + 1)
                grid[0][c0] = grid[0][c0+1] = grid[1][c0+1] = grid[1][c0+2] = False

        # Type 2: {(1,c), (1,c+1), (0,c+1), (0,c+2)}
        if r0 == 1 and c0 + 2 < W:
            if not grid[1][c0+1] and not grid[0][c0+1] and not grid[0][c0+2]:
