def can_tile(h, w, shape_type='Z'):
    # shape_type 'Z' for {(0,1), (1,1), (1,0), (2,0)} and its rotations/reflections
    # Z-tetrominoes are:
    # 1. {(0,1), (1,1), (1,0), (2,0)}
    # 2. {(0,0), (1,0), (1,1), (2,1)}
    # 3. {(0,0), (0,1), (1,1), (1,2)}
    # 4. {(0,2), (1,2), (1,1), (2,1)}
    # Wait, let's just list all 8 possible rotations/reflections of a Z-tetromino.
    # A Z-tetromino can be seen as:
    # (0,1), (1,1), (1,0), (2,0)  (Z)
    # (0,0), (1,0), (1,1), (2,1)  (S)
    # (0,0), (0,1), (1,1), (1,2)  (Z rotated)
    # (1,0), (1,1), (0,1), (0,2)  (S rotated)
    # ... and their reflections.

    # Let's define the Z-shape and its 8 symmetries
    base_z = {(0, 1), (1, 1), (1, 0), (2, 0)}

    def get_symmetries(shape):
        symmetries = []
        current = shape
        for _ in range(4):
            # rotate 90
            current = {(y, -x) for x, y in current}
            # normalize
            min_x = min(x for x, y in current)
            min_y = min(y for x, y in current)
            normalized = frozenset((x - min_x, y - min_y) for x, y in current)
            symmetries.append(normalized)
            # reflect
            reflected = frozenset((-x, y) for x, y in normalized)
            min_rx = min(x for x, y in reflected)
            min_ry = min(y for x, y in reflected)
            symmetries.append(frozenset((x - min_rx, y - min_ry) for x, y in reflected))
        return list(set(symmetries))

    z_shapes = get_symmetries(base_z)

    grid = [[False for _ in range(w)] for _ in range(h)]

    def solve(cells_filled):
