        found = False
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    found = True
                    break
            if found: break

        if not found:
            return True

        # Try placing each shape that covers (r, c)
        for shape in z_shapes:
            # A shape can cover (r, c) in several ways.
            # One of the cells in the shape must be (r, c).
            for dr, dc in shape:
