        r, c = -1, -1
        found = False
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    found = True
                    break
            if found: break
        if not found: return True

        for shape in z_shapes:
            for dr, dc in shape:
                origin_r, origin_c = r - dr, c - dc
                possible = True
                placed_cells = []
                for sr, sc in shape:
