def can_tile_2xW_with_S_tetrominoes(W):
    import collections
    def is_tileable_by_dominoes(cells_set):
        if not cells_set: return True
        if len(cells_set) % 2 != 0: return False

        cells = list(cells_set)
        adj = collections.defaultdict(list)
        for i, (x, y) in enumerate(cells):
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) in cells_set:
                    adj[i].append(cells.index((nx, ny)))

        match = [-1] * len(cells)
        def can_match(u, visited):
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if match[v] < 0 or can_match(match[v], visited):
                        match[v] = u
                        return True
            return False

        count = 0
        for i in range(len(cells)):
            visited = [False] * len(cells)
            if can_match(i, visited):
                count += 1
        return count == len(cells) // 2

    all_cells = set((x, y) for x in range(W) for y in range(2))

    # Try all placements of one S-tetramino
    # Type 1: (x,1), (x+1,1), (x+1,0), (x+2,0)
    for x in range(W - 2):
        cells_s1 = {(x, 1), (x+1, 1), (x+1, 0), (x+2, 0)}
        if cells_s1.issubset(all_cells):
            remaining = all_cells - cells_s1
            if is_tileable_by_dominoes(remaining):
                return True

    # Type 2: (x,0), (x+1,0), (x+1,1), (x+2,1)
    for x in range(W - 2):
        cells_s2 = {(x, 0), (x+1, 0), (x+1, 1), (x+2, 1)}
        if cells_s2.issubset(all_cells):
            remaining = all_cells - cells_s2
            if is_tileable_by_dominoes(remaining):
                return True
    return False

