    #   First cell: (r,c)
    #   Relative: (0,0), (1,0), (1,1), (2,1)
    # Type 4: (r,c), (r+1,c), (r+1,c-1), (r+2,c-1)
    #   First cell: (r,c)
    #   Relative: (0,0), (1,0), (1,-1), (2,-1)

