                        cells.append((nr, nc))
                    else:
                        possible = False
                        break

                if possible:
                    for nr, nc in cells:
                        board[nr][nc] = True
                    if backtrack(idx + 1):
                        return True
                    for nr, nc in cells:
                        board[nr][nc] = False
            return False

        return can_tile(H, W)

